script:
let sigs = [
  ["qemu_pipe", "QEMU Pipe", "HIGH", "References /dev/qemu_pipe or qemu_pipe — standard emulator IPC channel"],
  ["goldfish", "Goldfish Device", "HIGH", "Goldfish virtual device reference (Android emulator hardware)"],
  ["ranchu", "Ranchu Device", "HIGH", "ranchu — the modern Android emulator board name"],
  ["genymotion", "Genymotion Marker", "HIGH", "Genymotion emulator reference"],
  ["vbox", "VirtualBox Marker", "MEDIUM", "VirtualBox reference (Genymotion/older emulators run on VBox)"],
  ["nox", "Nox Player Marker", "HIGH", "Nox emulator reference"],
  ["bluestacks", "BlueStacks Marker", "HIGH", "BlueStacks emulator reference"],
  ["ro.kernel.qemu", "QEMU System Property", "HIGH", "ro.kernel.qemu property check — classic emulator detection"],
  ["ro.build.fingerprint", "Build Fingerprint Probe", "MEDIUM", "Reads the build fingerprint — often used in emulator/integrity checks"],
  ["init.svc.qemud", "QEMUD Service Probe", "HIGH", "Queries the QEMU daemon service"],
  ["/dev/socket/qemud", "QEMUD Socket", "HIGH", "Direct QEMU daemon socket reference"]
];
for sig in sigs {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
}
